// Language JSON File Location
var language = localStorage.getItem('language');
// Default Language
var default_lang = 'pt-br';

// Translate
var translate = null;

// Set Selected Language
function setLanguage(lang) {
    localStorage.setItem('language', lang);
    language = localStorage.getItem('language');

    var data = {
        "language": language
    };

    //console.log(data);

    $.ajax({
        url: '/api/v1/language',
        type: "POST",
        data: JSON.stringify(data),
        dataType: "json",
        contentType: "application/json;charset=utf-8"
    });

    // Run Multi Language Plugin
    getLanguage()
}

function processTranslate() {
    // add selected language class to the body tag
    $('body').attr('class', language);
    // Loop through message in data
    $.each(translate, function (index, val) {
        (index === 'head') ? $(document).attr("title", val['title']) : false;
        // addBack('[key]') tambem cobre o caso raro de key= no mesmo
        // elemento que carrega o id= do container (ex.: test_in_progress_alert
        // em advanced_config.html) - find() sozinho nunca inclui o proprio no.
        $(index).find('[key]').addBack('[key]').each(function () {
            $(this).text(val[$(this).attr('key')]);

            if ($(this).attr('type') == 'hidden') {
                $(this).val(val[$(this).attr('key')]);
            }
        });
    });
    // Avisa paginas que tem texto montado dinamicamente em JS (fora do
    // mecanismo key=/JSON) para que possam se atualizar apos troca de idioma.
    $(document).trigger('languageChanged');
}

// Run Multi Language Plugin - sempre busca a traducao atual do equipamento
// via /api/v1/translate (serve direto do JSON embutido no firmware, custo
// desprezivel numa rede local) em vez de usar cache em localStorage. Um
// cache antigo mostrava texto desatualizado pra sempre apos uma atualizacao
// de firmware, ate alguem lembrar de dar localStorage.clear() manualmente
// (achado em 2026-08-05).
function getLanguage() {
    // Language on user preference
    (language == null) ? setLanguage(default_lang) : false;

    var data = {
        "language": language
    };

    $.ajax({
        url: '/api/v1/translate',
        type: "POST",
        data: JSON.stringify(data),
        dataType: "json",
        contentType: "application/json;charset=utf-8",
        success: function (lang) {
            translate = lang;
            processTranslate();
        }
    });
}

// Auto Loader
$(document).ready(function () {
    if (language != null && language !== default_lang)
        getLanguage(language);
});
